    # ── YEMEN ─────────────────────────────────────────────────────────────
    {
        "type": "case_study",
        "jurisdiction": "YE",
        "title": "Ethiopian Migrants Stranded in Yemen — Exploitation and Death During Civil War (2015-2023)",
        "summary": "IOM documented tens of thousands of Ethiopian migrants stranded in Yemen after Saudi Arabia's military intervention began in March 2015 closed regular migration routes. Migrants who had been transiting Yemen to Saudi Arabia found themselves trapped with no income, shelter, or protection. Estimates placed 15,000-20,000 Ethiopian migrants in Yemen at peak periods. Armed groups including Houthi forces and Saudi-aligned militias exploited stranded migrants as forced labor on checkpoints and military positions. IOM documented 1,000+ deaths among stranded Ethiopians between 2015 and 2020 from violence, starvation, and disease. Saudi Arabia's detention and summary deportation of Ethiopians via Yemen's Haradh border created additional vulnerability as deportees were often stranded in conflict zones.",
        "source": "IOM Yemen DTM / IOM 'Desperate Journeys' 2021 / Human Rights Watch Yemen 2020",
    },
